import java.nio.file.*;import java.util.*;import com.google.gson.*;import com.google.common.collect.ImmutableList;import com.iridium126.createmanaindustry.client.render.shaderpack.ShaderPackInventory;import net.irisshaders.iris.shaderpack.include.*;import net.irisshaders.iris.shaderpack.option.ShaderPackOptions;
public final class R8OptionProbe{public static void main(String[]args)throws Exception{Path out=Path.of(args[0]);Files.createDirectory(out);var m=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonObject();var captured=new TreeMap<String,String>();m.getAsJsonObject("options").entrySet().forEach(e->captured.put(e.getKey(),e.getValue().getAsString()));var inventory=ShaderPackInventory.readPack(Path.of("run/shaderpacks",m.get("pack").getAsString()));Path root=out.resolve("pack");for(var e:inventory.sources().entrySet()){Path p=root.resolve(e.getKey());Files.createDirectories(p.getParent());Files.writeString(p,e.getValue());}var roots=ImmutableList.copyOf(inventory.sources().keySet().stream().filter(n->List.of(".vsh",".fsh",".gsh",".tcs",".tes",".csh").stream().anyMatch(n::endsWith)).map(n->AbsolutePackPath.fromAbsolutePath("/"+n)).toList());var options=new ShaderPackOptions(new IncludeGraph(root,roots,false),captured);var values=new TreeMap<String,String>();options.getOptionSet().getBooleanOptions().keySet().forEach(k->values.put(k,Boolean.toString(options.getOptionValues().getBooleanValueOrDefault(k))));options.getOptionSet().getStringOptions().keySet().forEach(k->values.put(k,options.getOptionValues().getStringValueOrDefault(k)));var missing=new TreeMap<String,String>(captured);missing.keySet().removeAll(values.keySet());var extra=new TreeMap<String,String>(values);extra.keySet().removeAll(captured.keySet());var different=new TreeMap<String,Object>();values.forEach((k,v)->{if(captured.containsKey(k)&&!captured.get(k).equals(v))different.put(k,List.of(captured.get(k),v));});String base=Files.exists(root.resolve("world0/gbuffers_entities.vsh"))?"world0/gbuffers_entities":"gbuffers_entities";var entity=new ShaderPackOptions(new IncludeGraph(root,ImmutableList.of(AbsolutePackPath.fromAbsolutePath("/"+base+".vsh"),AbsolutePackPath.fromAbsolutePath("/"+base+".fsh")),false),captured);var entityKeys=new TreeSet<String>();entityKeys.addAll(entity.getOptionSet().getBooleanOptions().keySet());entityKeys.addAll(entity.getOptionSet().getStringOptions().keySet());entityKeys.removeAll(captured.keySet());var declarations=new TreeMap<String,Object>();for(String key:missing.keySet()){var files=new ArrayList<String>();for(var e:inventory.sources().entrySet())if(e.getValue().contains("#define "+key))files.add(e.getKey());declarations.put(key,files);}System.out.println("Entity extras: "+entityKeys+"; declarations: "+declarations);
String report=new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("captured_count",captured.size(),"reparsed_count",values.size(),"missing",missing,"extra",extra,"different",different));Files.writeString(out.resolve("option-diff.json"),report);System.out.println(report);}}
